INSERT INTO `products` (`pro_code`, `pro_name`, `pro_Qty`, `pro_price`, `pro_image`, `pro_detail`) VALUES
(30, 'ابنبات هل دار', 8, 20000, 'abnabat.jpg', 'آبنبات هل‌دار داستان طنزی از زبان یک کودک بجنوردی است که برادرش به جبهه می‌رود و اسیر می‌شود. مهرداد صدقی کتاب آبنبات هل‌دار را نوشته است و نشر سوره مهر آن را منتشر کرده.'),
(31, 'ادبیات موضعی دهم', 8, 30000, 'adabiat.jpg', 'ادبیات موضعی برای پایه ی دهم'),
(32, 'اینده حیات', 7, 80000, 'aiandehayat.jpg', 'محور اصلی این اثر هوشمندانه چندان نا آشنا نیست؛ تاثیر رشد جمعیت انسانی و «مصرف اسرافکارانه» برتنوع زیست شناختی سیاره ما چیزی شبیه فاجعه است. اما آنچه کتاب ویلسون را متمایز می سازد، شرح ظریف و برانگیزانندهد علت مهم بودن تنوع زیستی و تشخیص نحوه حفظ این توازن در طبیعت است.'),
(33, 'الیس ویلی', 9, 40000, 'alisvili.jpg', 'کتاب آلیس ویلی اثر اعظم فرخ زاد نشر آوای مهدیس'),
(34, 'آن من', 22, 50000, 'aneman.jpg', 'کتاب آن من حاوی یک رمان معاصر و ایرانی و عاشقانه است که در ۲۲ فصل نوشته شده است. این رمان در حالی آغاز می‌شود که راوی می‌گوید شخصیتی به نام «امیرپاشا»، لباسش را جلوی آینه مرتب کرد و گوشی‌اش را برداشت. این شخصیت دلهره داشت. راوی می‌گوید که «سایه» امروز قرار بود برود کارهای قراردادش را انجام بدهد، اما انگار امیرپاشا بیشتر دلهره داشت. امیرپاشا از پله پایین و بدون سروصدا از خانه بیرون رفت'),
(35, 'ارباب حلقه ها', 31, 66000, 'arbabhalgheha.jpg', 'جموعه ی «ارباب حلقه ها» سرشار از اطلاعات مستقیم و غیرمستقیم در مورد داستانی وسیع است که قدمتش به صدها سال قبل از ماجرای اصلی کتاب بازمی گردد.'),
(36, 'ارزو های دست ساز', 4, 66000, 'arezodastsaz.jpg', 'کتاب آرزوهای دست‌ساز اولین اثر از یک مجموعه تاریخ شفاهی با موضوع پیشرفت است که به ماجرای شکل‌گیری یک شرکت دانش‌‌‌‌‌‌‌‌‌‌‌‌‌‌‌‌‌‌‌بنیان می‌پردازد. شرکتی دانش‌بنیان در حوزه فناوری‌های الکترونیکی و کامپیوتری که اختراع دوربین ثبت تخلفات رانندگی یکی از معروفترین دستاوردهای آن است.'),
(37, 'ارزش همه چیز', 6, 97800, 'arzesh.jpg', '«ارزش همه چیز» نوشته‌ی ماریانا مازوکاتو، کاوشی پیشگامانه درباره‌ی مفهوم ارزش و تخصیص آن در اقتصادهای مدرن است. مازوکاتو مفاهیم رایج خلق و توزیع ارزش را به چالش می‌کشد و از خوانندگان می‌خواهد که در نقش بازیگران مختلف، در شکل‌دهی اقتصاد تجدیدنظر کنند. عنوان «ارزش همه چیز»، به‌طور خلاصه موضوع اصلی کتاب را در‌بر می‌گیرد'),
(38, 'اسفار کاتبان', 80, 443000, 'asfarkateban.jpg', 'اسفار کاتبان نخستین رمان از سه گانه ی ابوتراب خسروی است که داستان سعید پسر مسلمان و اقلیما دختر یهودی است. این دو قرار است تحقیقی درباره ی قدیسین و تاثیر آنها در رفتار های اجتماعی داشته باشند. انچه این رمان را از دیگر آثار مشابه متفاوت می کند نحوه ی روایت آن است روایتی که ریشه در ساختار ادبیات کلاسیک و کهن فارسی دارد ساخت داستان حرکت موازی چند روایت به همراه یکدیگر است. ابوتراب خسروی که از شاگردان گلشیری است تلاش می کند تا تجربه ای اصیل برای خواننده ایرانی پدید آورد چیزی که تحت تاثیر جریان های مدرن به دست فراموشی سپرده شده است'),
(39, 'اتش بدون دود', 44, 547000, 'atash.jpg', 'حرف اصلی این رمان عشق است. اما عشق نه از آن نوع معمولی که در دیگر کتاب‌ها خوانده‌ایم. عشقی پرشور که غرور و خشونت را هم در درونش می‌پرورد. در کنار عشق، زبان شاعرانه‌ی نادر ابراهیمی آنچنان زیبایی‌های ترکمن صحرا را تصویر می‌کند '),
(40, 'بادام', 31, 90000, 'badam.jpg', 'یون جه با یک بیماری مغزی به نام آلکسی تایمیا به دنیا آمد که بروز احساساتی مانند ترس یا خشم را برای او سخت می‌کند. او هیچ دوستی ندارد - دو نورون بادام شکلی که در اعماق مغزش قرار گرفته‌اند این کار را با او کرده‌اند - اما مادر و مادربزرگ فداکارش زندگی امن و رضایت‌بخشی را برای او فراهم می‌کنند. خانه ی کوچک آنها بالای کتابفروشی دست دوم مادرش است که با یادداشت های رنگارنگ تزئین شده است. '),
(41, 'باقی مانده تقسیم ناپذیر', 32, 77000, 'baghimande.jpg', 'شلینگ به دست می‌دهد. شلینگ مدت‌هاست در سایه فیلسوفانِ بزرگی نظیر کانت و هگل قرار گرفته است. ژیژک در این کتاب نشان می‌دهد که شلینگ پیشاهنگ ماتریالیسمِ دیالکتیکی مارکس و مفهومِ رانه و ناخودآگاهِ فروید است و وجوهِ مشترک تعیین‌کننده‌ای با هگل دارد. در فصلِ اول، اندیشه شلینگ بررسی می‌شود. در فصلِ دوم، مواجهه شلینگ و هگل به روی صحنه می‌رود و در فصلِ سوم، به یاری مفاهیمِ شلینگ و هگل، درباره مسائلِ امروزی تکنولوژی و فیزیک مدرن بحث می‌شود.'),
(42, 'باشگاه پنج صبحی ها', 14, 43000, 'bashgah.jpg', 'حتماً شما هم تاکنون این جمله را شنیده‌اید: سحرخیز باش تا کامروا شوی! شاید تصور کنید که این جمله چه‌قدر کلیشه‌ای و بی‌فایده است؛ بنابراین کتاب باشگاه پنج صبحی‌ها (The 5 AM Club) مناسب شماست تا به قدرت شگفت‌انگیز سحرخیزی پی ببرید و زندگی شخصی و حرفه‌ای خود را دگرگون کنید.'),
(43, 'بوفکور', 2, 46000, 'bofkor.jpg', 'بوف کور شناخته‌شده‌ترین اثر صادق هدایت نویسنده معاصر ایرانی، رمانی کوتاه و از شاهکارهای ادبیات سدهٔ ۲۰ میلادی است. این رمان به سبک فراواقع نوشته شده و تک‌گویی یک راوی است که دچار توهم و پندارهای روانی است.'),
(44, 'بحران اقتصاد جهانی', 53, 62000, 'bohran.jpg', 'کتاب حاضر به منظور بررسی سیاست اقتصادی و مالیه بین‌المللی، به بحران‌های اقتصاد جهانی در قرن بیست و یکم توجه دارد. در این نوشتار ضمن معرفی بانک مرکزی و شورای روابط خارجی در فدرال رزرو، درباره بانک تسویه حساب بین‌المللی می‌نویسد'),
(45, 'چرند و پرند', 30, 43000, 'charandoparand.jpg', 'چرند و پرند مجموعه نوشته‌های طنز اجتماعی و سیاسی علی‌اکبر دهخدا است که در قالب داستان‌کوتاه، اعلامیه، تلگراف، گزارش خبری و... نوشته شده‌است.\r\nاین نوشته‌ها در فاصله زمانی بین پیروزی انقلاب مشروطیت و شروع استبداد صغیر در در ۳۲ شماره هفته‌نامه صوراسرافیل به مدیریت جهانگیرخان شیرازی، و بعدتر در سه شماره صوراسرافیل که پس از شروع استبداد صغیر توسط دهخدا در سوییس چاپ شد، منتشر می‌شد.'),
(46, 'چشم هایش', 32, 66000, 'cheshmhayash.jpg', 'روایت بزرگ علوی از زبان یک زن، نشان دهنده‌ی اشرافِ عمیق وی به شخصیت زنان، حالات روحی و خلق و خوی آن‌هاست. عواطف و احساسات فرنگیس، احساسات درونی او، عشق عمیقش به نقاش معروف و بی‌پروا شدنی که این عشق نصیبش کرده بود، از چشم‌هایش یک داستان مهیج و به یاد ماندنی به وجود آورده است.'),
(47, 'داجرز', 11, 43000, 'dajerz.jpg', 'کتاب داجر داستان یک جوان به نام ایست است او عضو یک باند خطرناک در لس آنجلس است و توسط عمویش به همراه چند پسر نوجوان دیگر – از جمله برادر جوانتر ایست – برای کشتن یک شاهد کلیدی که در ویسکانسین پنهان شده است به سفر فرستاده می شوند. این سفر ایست را از شهری که هرگز آن را ترک نکرده به آمریکائی می برد که کاملا با او بیگانه است و در نهایت او را مجبور می کند تا با جایگاه خود در جهان دست و پنجه نرم کند و تصمیم بگیرد که می خواهد چه نوع مردی شود.'),
(48, 'دژ درون', 2, 39000, 'daron.jpg', 'کتاب «دژ درون» اثری است که اولین بار در سال 2021 به انتشار رسید. این کتاب، مقدمه ای عالی بر فلسفه «رواقی گری» برای افراد ناآشنا با این موضوع است، و همینطور برای کسانی که با این فلسفه آشنایی دارند و می خواهند دانسته هایشان را افزایش دهند، یا تغییر نگرشی را در زندگی خود ایجاد کنند.'),
(49, 'داستان دو شهر', 23, 90000, 'dastandoshahr.jpg', 'کتاب داستان دو شهر، رمانی نوشته ی چارلز دیکنز است که اولین بار در سال 1859 انتشار یافت. «بهترین روزگار و بدترین ایام بود.» دیکنز با این کلمات معروف، مخاطبین را وارد یکی از پرآشوب ترین دوره های تاریخ می کند: انقلاب فرانسه. از یورش به قلعه ی باستیل گرفته تا سقوط بی رحمانه ی تیغه های گیوتین، این نویسنده ی بزرگ انگلیسی با مهارت و هنری خیره کننده، بیم ها، امیدها، و فراز و فرودهای بی پایان این دوره ی پرهیاهو را به تصویر می کشد. قهرمان داستان این رمان، مردی تنبل و الکلی به نام سیدنی کارتن است که به خاطر الهام بخشی های یک زن، ایثار و ازخودگذشتگی را در خیابان های خون آلود پاریس به غایت خود می رساند. رمان داستان دو شهر، اثری فوق العاده جذاب از یکی از استادان بلامنازع ادبیات انگلیس است'),
(50, 'دُن کیشوت', 31, 65000, 'den.jpg', 'رمان دُن کیشوت با ارائه ی ساختاری جدید و نثری جذاب و سرزنده به شکلی گسترده به عنوان اولین رمان مدرن جهان شناخته می شود. دون کیشوت آن قدر جذب داستان های عاشقانه ی شوالیه ها شده که تصمیم می گیرد خودش هم به یک جور شوالیه تبدیل شود. او به همراه خدمتکار وفادارش، سانچو پانزا، پا به انواع و اقسام ماجراجویی های جذاب می گذارد. این دو شخصیت تکرارنشدنی با یکدیگر به دور دنیا می چرخند و یکی از جاودانه ترین داستان های تاریخ را رقم می زنند. رمان دون کیشوت برای بیش از چهارصد سال است که تخیل مخاطبین را مسحور جذابیت خود ساخته و تأثیر شگرفی بر نسل های مختلف نویسندگان، از جمله دیکنز، ملویل، فاکنر و بسیاری دیگر داشته است.'),
(51, 'دیلماج', 32, 89000, 'dilmaj.jpg', 'در این کتاب آنچه مدنظر ماست دستیابی به چهره واقعی میرزا یوسف است. اگر چه با وجود این همه اختلاف در منابع نیل به این هدف بسیار سخت مینماید قصد ما آن است که با دوری از پیش داوری گام به گام با دریافتهایی که از منابع موجود و مدارک مستند - خصوصا زندگی نامه خود نوشت او به دست میآید چهره میرزایوسف را هر چه دقیق تر و واقعی تر ترسیم کنیم و البته بدیهی است که برای شناخت او به شناخت دیگران آنان که با وی دمساز بوده اند نیز احتیاج داریم.'),
(52, 'دونه انار', 43, 21000, 'doneanar.jpg', 'این کتاب در خصوص تفسیر و تعبیر روان‌شناختی داستان‌های بومی و محلی ایرانی است. در کتاب سعی شده تا با پرداختن به جنبه‌های روان‌شناختی داستان‌ها در سطح ساده و عمیق‌تری به درک معنای درونی و مفهوم غنی و آموزندهٔ آنها پرداخته شود.'),
(53, 'دروس طلایی دوازدهم', 12, 61000, 'dorostalaii.jpg', 'دروس طلایی پایه دوازدهم'),
(54, 'شازده احتجاب', 22, 31000, 'egtehab.jpg', 'کتاب شازده احتجاب، رمانی نوشته ی هوشنگ گلشیری است که نخستین بار در سال 1969 وارد بازار نشر شد. در اواسط دهه ی 1920 و در خانه ای رو به ویرانی، آخرین بازمانده از خانواده ای اشرافی به خاطر ابتلا به بیماری سل به شکلی تدریجی در حال نزدیک شدن به مرگ است. دامنه ی قدرت و نفوذ این شازده ی سالخورده، اکنون به خانه اش تقلیل یافته؛ خانه ای که در آن، حسرت شکوه و عظمت نیاکان شازده دست از سر او برنمی دارد.'),
(55, 'املا اول دبستان', 31, 17000, 'emla.jpg', 'املا اول دبستان'),
(56, 'فقط احساس خوب', 2, 98000, 'faghatehsaskhob.jpg', 'احساسی که نسبت به خودتان و خواسته‌هایتان دارید در حقیقت گذرگاهی‌ست که می‌تواند شما را به مقصدی تاریک یا روشن برساند. حالا اگر این احساس خوشایند را با تصورِ داشتنِ چیزی که می‌خواهید همراه کنید، خیلی زود انرژی ناشی از آن را در ابعاد مختلف زندگی‌تان مشاهده خواهید کرد. شاید کمی غیرمعمول و عجیب به نظر بیاید، اما این فرمول تابه‌حال بارها به اثبات رسیده است.'),
(57, 'فریدریش نیچه', 6, 11000, 'farid.jpg', '...'),
(58, 'فارسی ', 4, 22000, 'farsi.jpg', 'فارسی اول دبستان'),
(1, 'فارسی دوم دبستان', 8, 34000, 'farsidovm.jpg', 'کتاب کار و تمرین فارسی دوم'),
(2, 'کیمیاگر', 7, 79000, 'kimiagar.jpg', 'سانتیاگو زادگاهش را رها می‌کند و به شمال آفریقا می‌رود تا در نزدیکی اهرام مصر گنجی مدفون‌شده را پیدا کند. پائولو کوئیلو (Paulo Coelho) در کتاب کیمیاگر (The Alchemist) با سبکی مشابه به داستان‌های شرقی، روایت‌گر قصه‌ی این پسر جوان است. او در مسیرش، با زنی کولی، مردی که خودش را پادشاه می‌داند و یک کیمیاگر آشنا شده و نیز عاشق فاطمه، دختر صحرا می‌شود.'),
(3, 'جامعه شناسی رمان', 61, 34000, 'gameshenasi.jpg', 'انگلس زمانی گفت که از بالزاک در مورد اقتصاد و سیاست بیشتر آموخته است تا از مطالعه اقتصاددانان و مورخان. گئورگ لوکاچ در این سلسله مقالات که در سالهای 1934 و 1935 نوشته شد و در سال 1951 تحت عنوان بالزاک و رئالیسم فرانسوی گردآوری شد، خوانشی مارکسیستی از بالزاک را دنبال می کند که با خود مارکس آغاز شده بود. او در اثری واقع گرایانه می نویسد: «همه عناصر تعیین کننده، انسانی و اجتماعی ضروری یک دوره تاریخی به هم نزدیک می شوند و به هم می رسند».'),
(4, 'هشت قاعده عشق', 32, 22000, 'ghaedeeshgh.jpg', 'عاشق شدن درست مانند زمانی‌ست که یک جام کریستال زیبا و چشم‌گیر را به دست شما می‌سپارند. این جام به همان اندازه که می‌تواند تماشایی و باارزش باشد، نیازمند نگهداری و توجه شماست تا آن را در برابر هرگونه آسیب احتمالی محافظت کنید. اما متأسفانه بیشتر افراد صرفاً می‌خواهند عشق را در زندگی‌شان به دست بیاورند و مثل قهرمان‌ قصه‌ها نیمه‌ی گمشده‌ی خود را پیدا کنند؛ درحالی‌که مهم یافتن عشق و تصاحب آن نیست، بلکه این تلاش برای ساختن عشق و بنا کردن آن همچون یک اثر هنری زیبا و رشک‌برانگیز است که اهمیت دارد.'),
(5, 'قرابت معنایی', 2, 66000, 'gharabtmanaii.jpg', 'قرابت معنایی کنکور'),
(6, 'گیله مرد', 5, 32000, 'ghilemard.jpg', 'گیله مرد یکی از مبارزان گیلان است. او مردی روستایی است که خان منطقه مالیات بی حساب و کتاب از او گرفته است. در جریان اعتراض به مالیات و در نبود گیله مرد، زن او را کشته و کودک شیرخواره اش تنها می ماند. چند وقت بعد نیز گیله مرد دستگیر می شود. او همراه دو مامور در جنگل و در شلاق باران به سوی فومن به راه می افتند. داستان در همین حرکت و اقامت در قهوه‌خانه نزدیک مقصد به تدریج باز می‌شود. گلیه مرد در فکر فرار است...'),
(7, 'گلبرگ زخمی', 21, 33000, 'golbarg.jpg', 'رمان گلبرگ زخمی به‌قلم سمیه نوروزی، یک راوی اول شخص دارد؛ دختر جوانی به‌نام سایه که کودکی سختی را از سر گذرانده و حالا در جوانی نیز تیره‌بخت شده. پدر سایه مرد درست و مهربانی بود، یک کارگر ساختمانی که تمام تلاشش را می‌کرد تا زندگی خوبی برای زن و بچه‌ی خود فراهم کند؛ آن‌ها زندگی نسبتاً خوبی داشتند، تا روزی که خاله‌ی سایه با مردی پولدار ازدواج کرد و از آن به بعد نسیم، مادرِ سایه به‌واسطه‌ی حسادت به خواهر و مقایسه‌ی وضع زندگی و همسر او با زندگی و همسر خودش، اوقات بسیار بدی را در خانه‌شان به وجود آورد.'),
(8, 'هابیت', 9, 51000, 'habit.jpg', 'دریاچه‌هایی از جنس طلا، آدم‌های کوتاه قد، حضور اژدهایی با قدرت خارق‌العاده و تالارهای سنگی تنها بخش کوچکی از ذهن خلاق جان تالکین هست که انعکاس آن‌ها را در کتاب‌هایش می‌بینیم. جان تالکین با نبوغی خاص و با تکیه بر علم و دانش خود در زبان و تاریخ قرون وسطی کتابی همچون «هابیت» را آفریده است. داستان «هابیت» علاوه بر این‌که علاقه‌مندان به کتاب‌های تخیلی و فانتزی را میخکوب کرده سینما دوستان ژانر فانتزی و حماسی را نیز جذب خود کرده است.'),
(9, 'هستی مرگ', 11, 43000, 'hastimarg.jpg', 'این کتاب روایت مواجهات من با مردن آدم‌های دور و نزدیکم است که خصوصا در دوران کودکی و نوجوانی تجربه کرده‌ام. در این روایت‌ها مسئله‌ام این بوده که چگونه می‌توانیم در برابر مرگ، معنای زندگی و وجود را پیدا کنیم.'),
(10, 'تیز هوشان هفتم', 11, 46000, 'hh.jpg', 'کتاب جامع تیز هوشان هفتم'),
(11, 'و انگاه هیچکس نماند', 23, 54000, 'hichkas.jpg', 'هفت مرد و سه زن به وسیله‌ی به بهانه‌های مختلف به جزیره‌ی سلجر دعوت می‌شوند تا تعطیلات خود را در آن جزیره‌ی دورافتاده بگذرانند. وجه اشتراک مسافران در این است که به دلیل اعمال خود در گذشته منجر به قتل یک نفر شده‌اند. این افراد پس از مدتی متوجه می‌شوند که توسط یک نفر به این جزیره دعوت شده‌اند، کسی که از اسرار هر ده میهمان باخبر است. این فرد ناشناس به شیوه‌ای عجیب شروع به کشتن حاضران جزیره می‌کند و نحوه‌ی قتل آن‌ها را با الهام از شعری کودکانه به نام ده پسربچه سرباز انتخاب می‌کند.'),
(12, 'هیروشیما', 32, 66000, 'hiroshima.jpg', 'کتاب هیروشیما (Hiroshima) اثر جان هرسی (John Hersey) از جهات گوناگونی از اهمیت بالایی برخوردار است. یکی از ویژگی‌های جالب این کتاب سبک نویسندگی آن است که از سبک «روزنامه‌نگاری نوین» بهره برده. در این سبک ادبی شاهد پیوند میان نوشتار غیر-داستانی با داستانی هستیم. به این منظور که یک اثر از «روزنامه‌نگاری نوین» با وجود آنکه براساس اسناد تاریخی نوشته شده و در حال «شرح و گزارش» است'),
(13, 'هنر گفت و گو های اگاهانه', 32, 66000, 'honar.jpg', 'در گفت‌وگوهای روزمره‌ی ما کژتابی‌هایی وجود دارد که ممکن است روابط دوستی یا یک ملاقات کاری را نابود کند. برای ایجاد ارتباطی مؤثر و سازنده، باید عادات منفی را در گفتگوهایمان کنار بگذاریم. کتاب هنر گفتگوهای آگاهانه نوشته‌ی چاک ویزنر  تأمل در گفتگو کردن را به ما می‌آموزد و از افتادن در دام‌های زبانی رایج جلوگیری می‌کند.چاک ویزنر در کتاب هنر گفتگوهای آگاهانه، چهار نوع مکالمه را معرفی و راه اثربخشی هریک را به مخاطب نشان می‌دهد. گفتگوهای مبتنی بر داستان‌های ذهنی، همیاری، خلاقیت و تعهد چهار مکالمه‌ی اصلی بشری هستند.'),
(14, 'هری پاتر و جام اتش', 33, 19000, 'jamatash.jpg', 'موضوع اصلی داستان پیرامون کودک یتیم یازده ساله‌ای به نام هری پاتر است که یک جادوگر می‌باشد و در دنیای معمولی در کنار خاله، شوهرخاله و پسرخاله‌اش در کنار مشنگ‌ها (غیر جادوگران) زندگی می‌کند. توانایی او ذاتی است و کودکانی مانند او برای کسب آموزش لازم برای موفقیت در دنیای جادوگری به مدرسه هاگوارتز دعوت می‌شوند.'),
(15, 'جنایت و مکافات', 24, 54000, 'jenayat.jpg', 'هفت سال پیش از نگارش کتاب جنایت و مکافات فئودور داستایوفسکی  در نامه‌اى به برادر خود، نوشته بود که طرح کلی چنین داستانی را در زندان و در دورانى که با درد و دریغ و سرخوردگى روزگار مى‌گذرانده، در ذهن خود خلق کرده است. او نوشته بود که این اثر، اقرارنامه‌اى‌ست در شکل رمان که قصد دارد آن را با خون دلش بنویسد. سرانجام او محصول نهایی این طرح را در سال 1866 به انتشار رساند.'),
(16, 'کابل 1400', 4, 88000, 'kabl.jpg', 'رمانی که ماجرایش در ماه‌ها و روزهای پیش از سقوط کابل در اسد (مرداد) ۱۴۰۰ می‌گذرد؛ روایتی از درون یک نهاد کمک‌رسان آلمانی در کابل با کارمندان افغان و مدیران غربی‌اش؛ قصه‌ی مهدی، صفاکاری (نظافتچی) که در خانه‌اش کلکسیونی از اعضای بدن‌های منفجرشده‌ دارد و می‌خواهد آن‌چه را که در تمام این روزها دیده بنویسد.'),
(17, 'کج باوری', 5, 21000, 'kajbavari.jpg', 'دن آریلی (Dan Ariely) به دنبال تجربه‌ی یک ماجرای شخصی، دست به نگارش کتاب کج‌باوری: چرا آدم‌های منطقی باورهای غیرمنطقی دارند زد. او می‌خواست بفهمد چرا آدم‌ها این‌قدر تحت تأثیر قرار می‌گیرند و چرا اطلاعات غلط را نه‌تنها باور، بلکه دنبال و پخش هم می‌کنند؟ چه عواملی باعث می‌شود یک انسان به‌ظاهر منطقی به باورهای غیرمنطقی برسد و از آن‌ها دفاع کند؟ بررسی این سؤال‌ها با همدلی، به‌جای قضاوت یا تمسخر، سبب شد تا آریلی از ترومایی که دچارش شده بود گذر کند و به‌جای بروز واکنشی خشمگینانه یا قهرآمیز، به بررسی علمی موضوع بپردازد.'),
(18, 'کمی بی شعور باشیم', 34, 12000, 'kamibashorbashim.jpg', 'دن آریلی (Dan Ariely) به دنبال تجربه‌ی یک ماجرای شخصی، دست به نگارش کتاب کج‌باوری: چرا آدم‌های منطقی باورهای غیرمنطقی دارند زد. او می‌خواست بفهمد چرا آدم‌ها این‌قدر تحت تأثیر قرار می‌گیرند و چرا اطلاعات غلط را نه‌تنها باور، بلکه دنبال و پخش هم می‌کنند؟ چه عواملی باعث می‌شود یک انسان به‌ظاهر منطقی به باورهای غیرمنطقی برسد و از آن‌ها دفاع کند؟ بررسی این سؤال‌ها با همدلی، به‌جای قضاوت یا تمسخر، سبب شد تا آریلی از ترومایی که دچارش شده بود گذر کند و به‌جای بروز واکنشی خشمگینانه یا قهرآمیز، به بررسی علمی موضوع بپردازد.'),
(19, 'کلیدر', 5, 16000, 'kelider.jpg', 'کلیدر اثر محمود دولت‌آبادی ماجرای زندگی خانواده‌ای کرد است که در شهر نیشابور زندگی می‌کنند. داستان این رمان که بلندترین اثر این نویسنده‌ی نام‌آشنای ایرانی است، تحت تاثیر فضای سیاسی ملتهب کشور در سال‌‌های پس از جنگ جهانی دوم در بین سال‌های 1325 تا 1327 شمسی روی می‌دهد. کلیدر در واقع نام روستا و کوهی در شمال شرقی ایران است.'),
(20, 'کلیشه ای اما با صدا قلب', 31, 76000, 'kelishe.jpg', 'در بسیاری از تجربه های زندگی همگی با هم به جدال این بازی خواهیم رفت، فقط ظاهر داستان متفاوت است.\r\nدر این خانه ما پاکی را می پرستیم. عمق فاجعه آنجاست که ما خود را نپذیریم، ابتدا خود را قبول کنید و بعد از آن اولویت بندی هایتان را بخش بندی کنید. از یاد نبرید که اول عاشق خودتان شوید که زندگی تازه شروع شود.\r\nبا قلب خود بخوانید.'),
(21, 'کتابخانه ی پاریس', 31, 54000, 'ketankhaneparis.jpg', 'در بسیاری از تجربه های زندگی همگی با هم به جدال این بازی خواهیم رفت، فقط ظاهر داستان متفاوت است.\r\nدر این خانه ما پاکی را می پرستیم. عمق فاجعه آنجاست که ما خود را نپذیریم، ابتدا خود را قبول کنید و بعد از آن اولویت بندی هایتان را بخش بندی کنید. از یاد نبرید که اول عاشق خودتان شوید که زندگی تازه شروع شود.\r\nبا قلب خود بخوانید.'),
(22, 'خانه شادی', 26, 13000, 'khaneshadi.jpg', 'قهرمان رمان خانه‌ی شادی، همسر و خانواده می‌خواهد، آرامش و ثروت و زندگی سعادتمند می‌خواهد، توجه و عشق و تنانگی می‌خواهد و ... ازهمین‌رو، هیچ‌کدام را فدای دیگری نکرده و شورش علیه جهان مردانه‌ی سرمایه‌سالار را در مسیری که می‌خواهد پیش می‌برد، هرچند هیچ شورشی بدون تلفات و درد و رنج نیست!'),
(23, 'خِرد ابرغوک ها', 28, 87000, 'kherad.jpg', 'در دوران جنگ جهانی دوم یک تیم تخریب زیر آب در نیروی دریایی ارتش آمریکا تشکیل شد که به افسران آن «مردان قورباغه‌ای» می‌گفتند. همچنین در این رسته به پرچم‌داران ارشد لقب «گاو نر»  داده شده بود که مسئولیت افسران مادون را به عهده داشتند. در آن سال‌ها فرماندۀ وقت نیروی دریایی، ریچارد لیون، به کارکشته‌های این تیم لقب «ابرغوک» را داد.'),
(24, 'خیرگی', 45, 98000, 'khiregi.jpg', 'بعضی از جذاب‌ترین داستان‌ها و روایت‌ها از دل حوادث اتفاقی و پیش‌بینی‌نشده به دنیا می‌آیند. داستان کتاب خیرگی نیز یکی از همان روایت‌های غافل‌گیرکننده است. علیرضا سیف‌الدینی نویسنده‌‌ای که قبل‌تر او را با آثاری همچون «پلنگ‌ خانم تنهاست» و نقد و ترجمه‌های موفق می‌شناختیم، حال، در اثر داستانی تازه‌ی خود که با تلاش انتشارات نیماژ تهیه شده، دوربین روایت را به دست یک دختر جوان می‌دهد تا برش‌های از سرگذشت و روایت‌های تامل‌برانگیز او را بخوانیم.'),
(25, 'خویشتن کشی', 32, 18000, 'khishtankoshi.jpg', 'در خویشتن کشی شخصیت اصلی، گرهارد سلب، دادستان سابقی است که به کارآگاه خصوصی تبدیل شده است. این کتاب شامل ترکیبی از رمز و راز و کاوش در جامعهٔ آلمان پس از جنگ و مسائل اخلاقی است. خویشتن کشی به داستان‌های پیچیده‌ای از جرم، گناه و سایه‌های گذشته می‌پردازد و مهارت شلینک را در استفاده از موضوعات متفکرانه در داستان‌های کارآگاهی نشان می‌دهد.'),
(26, 'خوب های بد بد های خوب', 32, 18000, 'khobhayebad.jpg', 'اولین آدم‌ربایی در روستای گاوالدون دویست سال پیش اتفاق افتاده بود. معمولاً دو تا پسر یا دو تا دختر و گاهی یکی از این‌ دو ربوده شده بودند. سن بچه‌های ربوده‌ شده متفاوت بود: گاهی یکی شانزده ساله بود و دیگری چهارده ساله یا اینکه هر دو تازه دوازده ساله شده بودند. اوایل انتخاب‌ها تصادفی به نظر می‌رسید، اما چیزی نگذشت که الگوی آن مشخص شد: یکی از آن دو نفر همیشه زیبا و خوب بود؛'),
(27, 'خودت باش دختر جان', 2, 65000, 'khodtbash.jpg', 'ریچل هالیس مفاهیمی چون خودباوری، مسئولیت‌پذیری و لازمه‌های زندگی شاد و رضایتمندی را در زندگی زنان و دختران، در کتابی با عنوان خودت باش دختر مطرح کرده است. هالیس در این کتاب به زبانی ساده و روان تصاویر قالبی شکل گرفته توسط جامعه، رسانه و خانواده را مورد بررسی قرار می‌دهد، سپس الگوی طبیعی و روش دیگری برای خوشبختی ترسیم و معرفی می‌شود. ریچارد هالیس در مقدمه کتابش و در نامه‌ای سرگشاده به تمامی دختران و زنان اینطور نوشته‌ است: «کدام حقیقت؟ تو و فقط خود تو مسئول آدمی هستی که می‌شوی و همچنین مسئول میزان شادی و رضایتی که از زندگی داری.'),
(28, 'خون خورده', 31, 45000, 'khonkhorde.jpg', 'ذهن آدمی این قدرت را دارد تا فارغ از مکان و زمان به پرواز در‌آید و شروع به داستان‌سرایی ‌کند. جریان سیال ذهن یکی از عناصر ادبی است که با آن می‌توان به هر نقطه‌ای از تاریخ سفر کرد. نویسندگان زیادی هستند که با استفاده از این عنصر ادبی؛ تخیل خود را پرواز می‌دهند و داستان‌های جذاب خلق می‌کنند.'),
(29, 'مغازه خودکشی', 18, 54000, 'maghazekhodkoshi.jpg', 'بعضی رمان‌ها خلاف جریان آب شنا می‌کنند و این داستان را بسیار خواندنی‌تر و جذاب‌تر می‌کند. کمدی سیاه یک ژانر معروف در ادبیات است که با بیان واقعیات جامعه به زبان طنز سعی دارد هم از اتفاقات جامعه بگوید و هم با روایت کمدی لبخند بر روی لب خواننده بیاورد.'),
(59, 'هری پاتر و محفل ققنوس', 18, 19000, 'mahfel.jpg', 'موضوع اصلی داستان پیرامون کودک یتیم یازده ساله‌ای به نام هری پاتر است که یک جادوگر می‌باشد و در دنیای معمولی در کنار خاله، شوهرخاله و پسرخاله‌اش در کنار مشنگ‌ها (غیر جادوگران) زندگی می‌کند. توانایی او ذاتی است و کودکانی مانند او برای کسب آموزش لازم برای موفقیت در دنیای جادوگری به مدرسه هاگوارتز دعوت می‌شوند.'),
(60, 'ماهی سیاه کوچولو', 23, 65000, 'mahomahi.jpg', 'قصه‌ی ماهی سیاه کوچولو، از جایی آغاز می‌شود که یک ماهی پیر، حکایت زندگی ماهی کوچولویی را برای دوازده هزار ماهی کوچولوی دیگر تعریف می‌کند. ماهی سیاه کوچولوی قصه، در کنار مادرش در یک جویبار زندگی می‌کرد، اما کنجکاوی و روحیه‌ی ماجراجوی او چندان با زندگی تکراری‌اش همخوانی نداشت. بنابراین، این ماهی تصمیم گرفت برای دیدن انتهای جویبار راهی یک سفر شود.'),
(61, 'ملکوت', 43, 76000, 'malakot.jpg', ' ملکوت یک داستان بلند از بهرام صادقی، نویسندهٔ کتاب «سنگر و قمقمه‌های خالی» است. داستان ملکوت با روایت حلول جن در «آقای مودت» آغاز می‌شود. این داستان نخستین‌بار در «جلسات ادبی جنگ اصفهان» خوانده شد؛ داستانی که به‌وسیلهٔ مترجم مغربی «دکتر احمد موسی» به زبان عربی هم ترجمه و توسط انتشارات الربیع در قاهره در سال ۲۰۱۸ چاپ و منتشر شد.'),
(62, 'ماجرای من و درسام', 43, 76000, 'manodarsam.jpg', 'ماجرای من و درسام جامع دوم دبستان'),
(63, 'مزرعه حیوانات', 38, 74000, 'mazraee.jpg', 'در این کتاب هر حیوانی نماد یک چهره‌ی خاص یا نماینده‌ی یک گروه است. خوک‌ها، که قدرت خواندن، نوشتن، و سازمان‌دهی دارند، روشنفکران بُلشویکی هستند که دستگاه اداری وسیع شوروی را تحت کنترل خود داشتند. ناپلئون، استالین است، دسته‌ی اطراف وی پالیتبورو (کمیته‌ی اجرایی) هستند، اسنوبال، تروتسکی است، و اسکوالر نیز نماد پروپاگاندیست‌های رژیم است. خوک‌ها از امتیازهای تعلق‌داشتن به یک طبقه‌ی حاکم جدید (مانند غذای مخصوص و ساعات کار کوتاه‌تر) برخوردار هستند، بااین‌حال از نتایج زیر سوال‌رفتن سیاست‌های ناپلئون نیز رنج می‌برند.'),
(64, 'ملت عشق', 21, 12300, 'melateshgh.jpg', 'ملت عشق نام رمانی است نوشته الیف شافاک (الف شفق) که در سال ۲۰۱۰ / ۱۳۸۹ به صورت هم‌زمان به دو زبان انگلیسی و ترکی منتشر شد. این کتاب در رده سنی بالای ۱۲ سال است . این کتاب تاکنون بیش از ۵۰۰ بار (۵۵۰٬۰۰۰ نسخه) در ترکیه تجدید چاپ شده و توانسته رکورد پرفروش‌ترین کتاب تاریخ ترکیه را نیز به دست آورد. ترجمه فارسی آن در مدتی کوتاه، عنوان یکی از پرفروش‌ترین کتاب‌های بازار کتاب ایران را کسب کرده‌است.'),
(65, 'متاآنالیز', 1, 35200, 'metaanaliz.jpg', 'گفته شده است که کنار هم قراردادن شواهد در علم آمار زیستی، مجموعه مطالعاتی به وجود آورده است که «متاآنالیز» یا «فراتحلیل» نام دارد. کتاب متاآنالیز در این باره است. ناصر حاتمی توضیح داده است که در متاآنالیز، اطلاعات موجود در مطالعات پیشینْ جمع‌آوری شده، تحلیل و سنجیده می‌شود تا بتواند به شناسایی و ارزیابی ناهمگونی‌های موجود در داده‌ها کمک کند. عنوان برخی از فصل‌های این کتاب عبارت است از «فراتحلیل داده‌های بیمار فردی»، «رویکردهای مواجهه با بیاس انتشار»، «تست حساسیت در متاآنالیز»، «فراتحلیل داده تجمیعی» و «فراتحلیل یا متاآنالیز».'),
(66, 'مدیر مدرسه', 7, 34000, 'modirmadrese.jpg', 'کتاب  مدیر مدرسه داستان معلمی است که از شغلش خسته شده و برای داشتن درآمد و آسودگی بیشتر با رشوه و راهکار‌های فاسد می‌خواهد مدیر مدرسه بشود، ولی نمی‌داند چه اتفاقاتی خواهد افتاد. سرانجام مدیر مدرسه‌ای با هفت معلم، یک ناظم و دویست و پنجاه دانش‌آموز می‌شود، وقتی به خودش می‌آید، خود را میان انسان‌ها و درگیری‌هایشان پیدا می‌کند'),
(67, 'نامیرا', 9, 33000, 'namira.jpg', 'کربلا اثرگذارترین واقعه‌ی تاریخ اسلام شیعی و نمایش صف کشیدن حق علیه باطل است. یادگار «امیرمؤمنین (ع)» و «فاطمه‌الزهرا (س)» شمشیرها را به آغوش کشید تا دین جدش را زنده نگه‌ دارد و نشان دهد حق همواره پیروز است. بیش از ۱۴ قرن از این رخداد سربلندی و مردانگی می‌گذرد اما هنوز هم می‌توان از این واقعه بسیار آموخت.'),
(68, 'دایی جان ناپلئون', 55, 28000, 'napelon.jpg', 'طنزنویسی در ادبیات ایران سابقه‌ای دیرینه‌ دارد. از زمانی که «عبید زاکانی» منظومه «موش و گربه» را سرود تا امروز، آثار طنز ماندگاری در ادبیات فارسی نوشته شده است. تعداد زیادی از این آثار طنز از سلاح قلم برای بیان ضعف‌های جامعه استفاده کرده‌اند و این شیوه‌ی نقد اجتماعی از ادبیات کلاسیک به ادبیات معاصر هم رسیده است.'),
(69, 'ناطور دشت', 12, 90000, 'natoredasht.jpg', 'رمان ناطور دشت نوشته‌ی جروم دیوید سلینجر درباره‌‌ی نوجوانی به نام هولدن کالفیلد است که ماجرای اخراج خود از مدرسه را روایت می‌‌کند، اما محتوای اثر به انتقاد از ارزش‌‌های مصرف‌‌گرایی و عوام‌‌فریبی در آمریکای دهه‌‌ی پنجاه میلادی می‌‌پردازد. به دلیل انتقادهای به‌‌روز و دقیق نویسنده، این اثر به‌سرعت توسط خوانندگان، دست به دست شد و توانست به‌عنوان یکی از مظاهر ادبیات کلاسیک در قرن بیستم در محافل مختلف ادبی شناخته شود.'),
(70, 'گام به گام دهم', 18, 110000, 'nn.jpg', 'گام به گام دهم تجربی'),
(71, 'نقطه میخواست فرار کند', 32, 970000, 'noghte.jpg', 'کتاب نقطه می خواست فرار کند که با تصویرسازی‌های «جانلوکا بوتُلو» منتشر شده، قصه‌ای نوشتهٔ هشام مطر است؛ قصه‌ای که سردرگمی و ابهام نقطه در جهانی وسیع و حیرت‌انگیز را روایت می‌کند. این کتاب سفری به جهان نشانه‌ها است. در هر سن‌‌وسالی که هستیم با مطالعهٔ این کتاب، با سؤال‌هایی روبه‌رو می‌شویم که روز‌به‌روز با ما بزرگ و بزرگ‌تر شده‌اند. این داستان، در دستهٔ کتاب‌های هویتی قرار گرفته است؛ مرزبندی مشخصی برای سن‌وسال خوانندگانش در نظر نمی‌گیرد؛'),
(72, 'پایان کیمیا گری', 32, 450000, 'paian.jpg', 'انقلاب صنعتی عصرِ کاپیتالیستی امروزین را پی افکند. با وجود این، شکوفایی ابداعات تکنولوژیک در طی آن دورانِ پویا متکی بود بر پذیرش گستردۀ دو ایدۀ بسیار قدیمی‌تر: خلق پول کاغذی و ایجاد بانک برای صدور اعتبار. هردو ایده در بنیادِ خود انقلابی هستند و کم و بیش جادویی. کاغذ معمولی به ارزشمندی طلا شد و سپرده‌های کوتاه‌مدت امن تبدیل شدند به وام‌های بلندمدت پرخطر.'),
(73, 'پاییز فصل اخر سال است', 43, 870000, 'paiiz.jpg', '«پاییز فصل آخر سال است»‌ نوشته نسیم مرعشی( -۱۳۶۲) و برگزیده بخش رمان جایزه جلال آل احمد است.\r\nاین رمان برش‌هایی از زندگی سه دختر در آستانه‌ی سی سالگی است. سه دختر که زندگی‌شان از در دوران دانشگاه با هم گره خورده و حالا در حالی که راهشان کاملا از هم جداست، کماکان روی زندگی هم تاثیر می‌گذارند. کتاب «پاییز فصل آخر سال است» دو بخش با عنوان‌های «تابستان» و «پاییز» دارد. هر کدام از این دو بخش شامل سه فصل است که هر فصل از نگاه یکی از شخصیت‌های رمان روایت می‌شود.'),
(74, 'پینوکیو', 21, 97000, 'pinokio.jpg', 'پینوکیو که بهترین اثر کارلو کلودی است، یکی از بزرگترین شاهکارهای ادبیات جهان نیز به شمار می‌رود. بر طبق آمار، بیشترین تعداد ترجمه به زبان‌های مختلف در ادبیات جهانی متعلق به این اثر است. این آگاهی می‌تواند موجب شگفتی باشد. بی‌تردید اندیشیدن به این امر دشوار است که بیشترین تعداد ترجمه متعلق به اثری برای کودکان باشد؛ اما این‌چنین است، زیرا نه تنها به تمام زبان‌ها و گویش‌های جهان ترجمه شده، بلکه تعداد ترجمه‌های آن بسیار زیاد است.'),
(75, 'ریاضی دهم', 22, 62000, 'pp.jpg', 'ریاضی دهم سیر تا پیاز'),
(76, 'رنج دگرگونی', 27, 98000, 'ranj.jpg', 'رمان «رنج دگرگونی» پنجمین اثر تألیفی احسان عبدی به مانند چهار کتاب پیشین وی با رویکردی اجتماعی، نگاهی عمیق به درون انسان، نقاط ضعف و قوت او و تلاش برای رهایی از مصائب و مشکلات درونی‌اش دارد. این رمان، روایتگر احوالات جوانی است که برای رهایی از رنج‌های خودخواسته به‌دنبال راه چاره‌ می‌گردد.'),
(77, 'راز داوینچی', 14, 98000, 'raz.jpg', 'کتاب راز داوینچی (The Da Vinci Code) در سال ۲۰۰۳ منتشر شد. دن براون در این کتابٰ داستانی معمایی را به یک تئوری قدیمی مرتبط می‌کند و ماجرایی هیجان‌انگیز می‌آفریند. گره‌گشایی، رمزنگاری و جواب دادن به سوالاتی عمیق و بی‌پایان، از ویژگی‌های این داستان است.'),
(78, 'ربه کا', 4, 89000, 'rebeka.jpg', 'نوع روایت زیبا و تاثیرگذار داستان ربه‌کا باعث شده تا خواننده در تمام موقعیت‌ها و اتفاق‌ها به دنبال سرنوشت شخصیت‌ها باشد. ربکا جزو آن دسته از کتاب‌های پرکشش و خوش‌خوانی است که تا آن را تمام نکنید، نمي‌توانيد رهایش ‌کنید. یکی از افرادی که این موضوع را به خوبی درک کرد «آلفرد هیچکاک» کارگردان بزرگ آمریکایی بود که فیلم فوق‌العاده‌‌ای براساس داستان این کتاب ساخت.'),
(79, 'ریاضیات پایه', 1, 89000, 'riaziat.jpg', 'ریاضیات پایه '),
(80, 'ریاضی دهم', 5, 99000, 'riazidahom.jpg', 'ریاضی دهم ای کیو'),
(81, 'کتاب کار ریاضی', 5, 99000, 'riazido.jpg', 'کتاب کار ریاضی دوم'),
(82, 'کتاب کار ریاضی دوم', 5, 99000, 'riazidovom.jpg', 'کتاب کار ریاضی دوم مینا داودی'),
(83, 'ریاضی هفت ام', 5, 99000, 'riazihaft.jpg', 'کتاب کار ریاضی هفتم'),
(84, 'ریاضی نهم', 8, 44000, 'riazinoh.jpg', 'ریاضی سیر تا پیاز نهم'),
(85, 'ریاضی نهم کارپاچینو', 7, 25000, 'riazinohom.jpg', 'ریاضی نهم کارپاچینو'),
(86, 'رویای نیمه شب', 3, 86000, 'royanimeshab.jpg', 'کتاب رویای نیمه شب نوشته مظفر سالاری با ترکیب مناسبی از داستان عاشقانه و زمینه مذهبی، یک تجربه مطالعه جذاب و متفاوت را به خوانندگان ارائه می‌دهد. این داستان، ارتباط عاشقانه بین دو شخص با پس‌زمینه‌های مذهبی متفاوت را روایت می‌کند و نشان می‌دهد که چگونه عوامل فرهنگی و مذهبی می‌توانند بر روی روابط انسانی تأثیر بگذارند.'),
(87, 'قهوه سرد اقای نویسنده', 32, 32000, 's18.jpg', 'کتاب قهوه‌ی سرد آقای نویسنده یک رمان ایرانی با موضوع عاشقانه است که تمِ معمایی – هیجانی دارد و در مدت زمان تقریبا یک ماهه به چاپ بیستم رسیده و می‌توان گفت به نحوی شگفتی ساز است. این رمان تا به امروز بیشتر از پنجاه بار تجدید چاپ شده است.\r\nاین رمان داستان یک نویسنده به نام آرمان روزبه و یک دختر روزنامه‌نگار است. کتاب با یک خاطره از دروان کودکی آرمان شروع می‌شود. خاطره‌ای که در ادامه اساس اتفاقات بعدی کتاب است.'),
(88, 'سمفونی مردگان', 31, 77000, 's21.jpg', '«قبل از هرچیز باید گفت که سمفونی مردگان یک شاهکار است». این جمله در نشریه‌ی دی‌ولت سوئیس منتشر شده است و به زیبایی هرچه تمام‌تر سمفونی مردگان را توصیف کرده است. کتابی که هرچند روایتی از درد، اندوه، سختی و بدبختی است، اما زیبا و در نوع خود یک شاهکار است. سمفونی مردگان داستان خانواده‌ای است که در آذربایجان زندگی می‌کنند.'),
(89, 'سال بلوا', 21, 83000, 'salbalva.jpg', 'کتاب سال بلوا (The Year of Turmoil) داستان زندگی دختری به نام نوش‌آفرین است که زندگی خود را در بستر مرگ و بیماری، به یاد می‌آورد. عباس معروفی  داستان این کتاب را در سال‌های پیش و پس از جنگ جهانی دوم در شهر سنگسر روایت می‌کند. نوش‌آفرین دختر زیبای سرهنگ نیلوفری و عالیه خانم است که پدرش رؤیای ملکه شدن او را در سر دارد.'),
(90, 'سالتو', 11, 8382000, 'salto.jpg', 'سیاوش از زمانی که به یاد داشت عاشق کشتی بود. دیدن تشک، شنیدن صدای سوت داوران و تشویق تماشاچی‌ها باعث می‌شد خون به صورتش بدود و همه‌چیز را فراموش کند: پدر معتادش، مادرش که در خانه‌ای با سقف ایرانیتی زندگی می‌کرد، دوستانی که سر چهار راه دستمال و گل می‌فروختند و حتی آن همسایه‌ای که با لباس‌های شیک و تمیز خودش را به ماشین‌های بالای شهر می‌زد تا از آن‌ها برای شکایت نکردن پول بگیرد و به کلاهبرداری کوچک خود فخر بفروشد.'),
(91, 'سرمای قطبی', 25, 23000, 'sarmayeghotbi.jpg', 'حدس زدن سنش راحت بود، اما اینکه از کجای این دنیا آمده موضوع را کمی سخت می‌کرد.\r\nده ساله به نظر می‌رسید. کاپشن خاکستری‌رنگ به تن داشت که زیپش را نبسته بود. شال‌گردن روی گردنش انداخته بود و شلوار ارتشی به پا داشت. کوله‌ی مدرسه‌اش هم پشتش بود. یکی از کفش‌هایش پاره شده و سوراخ روی جورابش پیدا بود. پسر کلاه و دستکش نپوشیده و موی سیاهش یخ زده بود.'),
(92, 'سرزمین بلاخیز', 9, 27000, 'sarzamin.jpg', 'استعمار و استثمار، تاریخی به قدمت قرون و اعصار دارد، از ساخت اهرام مصر در هزاران سال پیش و شاید قبل از آن در تاریخ مدون بشری تا اواخر قرن بیستم و شاید به نوعی دیگر و در پوششی جدید در قرن بیست و یکم. استعمار و استثمار هیچ‌گونه رحم و شفقتی برنمی‌تابد. برای او گویی بی‌ارزش‌ترین چیزها جان انسان‌هاست.'),
(93, 'شفای زندگی', 9, 29000, 'shafayzendegi.jpg', 'همه‌ی ما در زندگی به کتاب‌هایی نیاز داریم تا تحت تاثیرشان قرار بگیریم. کتاب‌هایی که باید در کنار رمان‌ها و داستان‌های روزمره‌ی خود بخوانیم و از خواندن آن‌ها درس زندگی بگیریم. بدون شک کتاب شفای زندگی یکی از بهترین نمونه‌های این نوع کتاب‌ها است. کتابی از ابتدا تا انتهایش خواننده را مسحور خودش می‌کند و نمی‌گذارد خواننده لحظه‌ای نور امید را فراموش کنند.'),
(94, 'شریف جان شریف جان', 9, 29000, 'sharifjan.jpg', 'خواندن داستان از زمان و مکانی دیگر علاوه بر اینکه خواننده را به نقطه‌ای دیگر از تاریخ می‌برد شرایط اجتماعی و نحوه‌ی زندگی افراد در آن دوره را نیز نشان می‌دهد. تاریخ پر است از وقایع و رویدادهایی که دست‌مایه‌ی قلم توانای نویسندگان شده است تا در قالب داستان‌های خواندنی آن‌ها را برای نسل‌های بعد به ارث بگذارند. تاریخ ایران همچون سرزمین‌های دیگر مملو از فرازوفرودهای سیاسی و اجتماعی است که نویسندگان گوناگون به تأثیر از آن‌ها داستان‌های ماندگاری خلق کرده‌اند.'),
(95, 'شازده کوچولو', 80, 32000, 'shazde.jpg', 'خلبانی که در یک بیابان گیر افتاده است، یک روز صبح از خواب بیدار می‌شود و می‌بیند که در مقابل او، فردی کوچک و خارق‌العاده ایستاده است. غریبه می‌گوید: «لطفا برای من یک گوسفند بکش» و خلبان متوجه می‌شود که وقتی درک وقایع زندگی بسیار دشوار است، چاره‌ای جز تسلیم اسرار آن شدن وجود ندارد.'),
(96, 'شیطان در پیراهن ابی', 29, 53000, 'sheytan.jpg', 'داستان کتاب شیطان در پیراهن آبی به قلم والتر موزلی ما را با خود به خیابان‌های پایین‌شهر لس آنجلس در سال 1948 می‌برد. جنگ جهانی دوم به تازگی پایان یافته و ناامنی، فساد و جنایت در لس آنجلس بیداد می‌کند. ایزی رالینز جوانی سیاه‌پوست است که به تازگی از جنگ جهانی بازگشته و خیلی زود از کارش نیز اخراج شده است.'),
(97, 'تمرکز رادیکال', 39, 89000, 'tamarkoz.jpg', 'کتاب تمرکز رادیکال در نظر دارد به همۀ سازمان‌ها کمک کند تا مانند بهترین سازمان‌ها فعالیت خود را آغاز کنند. این تکنیک‌ها به‌طور موفقیت‌آمیزی در سازمان‌هایی به بزرگی یک شرکت با شصت‌هزار کارمند تا یک استارت‌آپ سه‌نفره به کار گرفته می‌شود'),
(98, 'تاریخ المان', 69, 96000, 'tarikhalman.jpg', 'ین کتاب به بررسی تاریخ آلمان از سال 1914 تا سال 2020 می‌پردازد و نشان می‌دهد که چگونه این کشور از یک امپراتوری قدرتمند و متمرکز، به یک جمهوری ضعیف و متلاشی و سپس به یک دیکتاتوری وحشتناک و متجاوز و درنهایت به یک کشور تقسیم‌شده و دوباره متحدشده تبدیل شد. این کتاب با استفاده از منابع متنوع و مستند، رویدادها، شخصیت‌ها، ایدئولوژی‌ها، فرهنگ‌ها و جامعه‌های مختلفی را که در تاریخ آلمان نقش داشته‌اند، مورد بررسی و تحلیل قرار می‌دهد.'),
(99, 'تاریخ اسلام', 1, 100000, 'tarikheslam.jpg', 'تاریخ در پیوند با زمان و انسان معنا می یابد و حتی تأثیر تاریخ و گذر زمان نه تنها در یک فرد که در ملت ها و نژادها روشن است. باید اندیشید و در نهایت به داوری نشست. نویسنده با همین اندیشه، می خواهد دفتر قطور تاریخ را به رویمان بگشاید و از اسلام بنویسد. وی این مجموعه را در پنج بخش اصلی و شانزده فصل تدوین کرده است و می کوشد تا برای هر یک از حوادث عصر نبوی، منابع جداگانه و متنوعی بیاورد. همچنین با بیان شواهد قرآنی و حدیثی، حوادث را از شکل گزارش صرف بیرون آورده و به تحلیل و بررسی مناسب برخی از آنها پرداخته و به شبهه های مربوط به هر موضوع نیز توجه کرده است.\r\n'),
(100, 'تسلیم نشو یومی چانگ', 20, 220000, 'taslimnasho.jpg', 'کتاب تسلیم نشو یومی چانگ!  اثری بامزه و جالب توجه از جسیکا کیم  است. این رمان جذاب، پرمغز و سرشار از بازیگوشی در مورد دختری به نام یومی چانگ است که روزهایش را در یک رستوران در کنار خانواده‌اش سپری می‌کند. حضور در این مکان خانوادگی باعث شده تا برخلاف خواسته‌اش همیشه بوی غذا بدهد و همین مسئله دلیلی می‌شود که توسط همکلاسی‌هایش با کلمات و القاب عجیبی خطاب شود. اما یومی چانگ شخصیتی نیست که با این توصیفات مسخره از سوی دیگران به افسردگی مبتللا شود و احساس درماندگی کند.'),
(101, 'وارثان', 30, 120000, 'varesan.jpg', 'ویلیام جرالد گلدینگ در نوزدهم سپتامبر سال 1911 در شهرک بندری ماهیگیری نیوکی در کورنوال انگلستان در منزل مادربزرگش چشم به جهان گشود. گلدینگ به‌عنوان یک رمان‌نویس، نمایشنامه‌نویس و شاعر که بیشترین شهرت خود را مرهون رمان \"سالارمگس‌ها\" می‌باشد در سال 1983 به‌علت خلق این اثر فاخر برنده جایزه نوبل ادبی گردید. در سال 1980، نیز جایزه بوکر در ادبیات به‌خاطر رمان\"مناسک عبور\" که اولین کتاب مجموعه سه‌گانه ادبی او تحت‌عنوان\" تا پایان‌های زمین\" که شامل \" مناسک عبور\"(1980) \"ربع‌های نزدی ...'),
(102, 'هری پاتر و یادگان مرگ', 40, 88000, 'yadegaranmarg.jpg', 'موضوع اصلی داستان پیرامون کودک یتیم یازده ساله‌ای به نام هری پاتر است که یک جادوگر می‌باشد و در دنیای معمولی در کنار خاله، شوهرخاله و پسرخاله‌اش در کنار مشنگ‌ها (غیر جادوگران) زندگی می‌کند. توانایی او ذاتی است و کودکانی مانند او برای کسب آموزش لازم برای موفقیت در دنیای جادوگری به مدرسه هاگوارتز دعوت می‌شوند.'),
(103, 'ذهن خوانی', 3, 37000, 'zehnkhani.jpg', 'ما در ارتباطات روزانه و مکالمات گفتاری یا نوشتاری خود به دنبال منظور اصلی کلام هستیم. هیچ‌کس نمی‌تواند بگوید معنای تمام حرف‌ها یا اتفاقاتِ پیرامونش را همیشه به‌درستی درک می‌کند. فهمِ معنای واقعیِ هرچیز، چه یک اثر هنری باشد، چه سخنرانی و چه مکالمه‌ای دوستانه، در ایجاد ارتباطی سالم با دیگران بسیار مهم است. کتاب ذهن‌خوانی نوشته‌ی دیوید جی. لیبرمن پیشرفته‌ترین متدها را برای پروش توانایی‌های شبه‌تله‌پاتی در اختیار مخاطب قرار می‌دهد.'),
(104, 'زیبا صدایم کن', 81, 97000, 'zibasedamkon.jpg', 'این کتاب توسط فرهاد حسن زاده به نگارش در آمده است. داستان این اثر داستانی جذاب با مرکزیت دختری پانزده ساله ای روایت می شود. دختر پانزده ساله‌ای است که در موسسه‌ای زیر نظر بهزیستی زندگی می‌کند. مادر معتادش ازدواج کرده و پدرش به سبب بیماری روانی در آسایشگاه بیماران روانی بستری است.'),
(105, 'زیست شناسی دهم', 29, 25000, 'zistdah.jpg', 'زیست شناسی دهم تجربی'),
(106, 'زیست شناسی دجامع', 31, 89000, 'zistshenasi.jpg', 'زیست شناسیجامع کنکور'),
(107, 'زیست شناسی', 41, 89000, 'zistshenasi.png', 'زیست شناسی خیلی سبز');
